<script>
import { Form, Head, Link } from '@inertiajs/vue3';
import InputError from '@scaffold/components/InputError.vue';
import PrimaryButton from '@scaffold/components/PrimaryButton.vue';
import { login } from '@app/routes';
import { email } from '@app/routes/password';

export default {
    name: 'ForgotPassword',
    components: { Form, Head, InputError, Link, PrimaryButton },
    props: { status: String },
    data() {
        return {
            resetLinkForm: email.form(),
            loginUrl: login.url(),
        };
    },
};
</script>

<template>
    <div>
        <Head title="Aizmirsāt paroli?" />
        <div class="row justify-content-center">
            <div class="lg:col-4 md:col-6 sm:col-8 ms-auto me-auto">
                <div class="card">
                    <div class="card-header card-header-primary text-center">
                        <h1 class="card-title h4">Aizmirsāt paroli?</h1>
                    </div>
                    <Form v-bind="resetLinkForm" v-slot="{ errors, processing }">
                        <div class="card-body">
                            <p>Norādiet savu e-pasta adresi. Nosūtīsim saiti paroles atjaunošanai.</p>
                            <p v-if="status" class="text-success" role="status" aria-live="polite">{{ status }}</p>
                            <div class="form-group">
                                <label for="forgot-email">E-pasta adrese</label>
                                <input id="forgot-email" name="email" type="email" class="form-control" autocomplete="email" required autofocus :aria-invalid="Boolean(errors.email)" :aria-describedby="errors.email ? 'forgot-email-error' : undefined">
                                <InputError id="forgot-email-error" :message="errors.email" />
                            </div>
                        </div>
                        <div class="card-footer justify-content-center">
                            <PrimaryButton type="submit" class="btn btn-primary" :disabled="processing">
                                {{ processing ? 'Nosūta…' : 'Nosūtīt atjaunošanas saiti' }}
                            </PrimaryButton>
                        </div>
                    </Form>
                    <p class="text-center mb-3"><Link :href="loginUrl">Atgriezties pie pieteikšanās</Link></p>
                </div>
            </div>
        </div>
    </div>
</template>
